// 1) Development — outside the repository entirely
// dotnet user-secrets init
// dotnet user-secrets set "ConnectionStrings:OrdersDb" "Server=(localdb);..."
var builder = WebApplication.CreateBuilder(args);
if (builder.Environment.IsDevelopment())
{
    builder.Configuration.AddUserSecrets(typeof(Program).Assembly);
}

// 2) Production — Key Vault provider on top of the default config chain
builder.Configuration.AddAzureKeyVault(
    new Uri("https://acme-secrets.vault.azure.net/"),
    new DefaultAzureCredential());   // managed identity on Azure, no secret stored

// 3) Read uniformly — the source swap needs no code changes
var conn = builder.Configuration.GetConnectionString("OrdersDb")!;
var apiKey = builder.Configuration["ThirdParty:Payments:ApiKey"]!;

// 4) SQL access via managed identity instead of a password in config
// az sql server ad-admin create ... ; connection string uses Active Directory Default

// What NOT to do:
// - "ConnectionStrings": { "OrdersDb": "..." } committed in appsettings.Production.json
// - Logging configuration at startup — secrets end up in App Insights
// - One shared key across services — rotation and blast radius become unmanageable
